+  pathD: string | null;
+  /** Total length of `pathD` in user units. */
+  pathLength: number;
+  /** Path length at which the dashed tail begins. */
+  dashStartLength: number;
+  /** X coordinate (chart inner space) where the tail clip begins. */
+  dashStartX: number;
+  innerWidth: number;
+  innerHeight: number;
+  /** Stroke paint — solid color or gradient url. */
+  stroke: string;
+  strokeWidth: number;
+  dashArray: string;
