+    const runShrink = (from: number) => {
+      const shrinkDuration = halfCycleS * ((1 - from) / 0.5);
+      controls = animate(progress, 1, {
+        duration: Math.max(shrinkDuration, 0.01),
+        ease: [...LINE_LOADING_PULSE_EASE],
+        onComplete: finish,
+      });
+    };
