+
+/** Deterministic up/down (±1) per bar for the "center" baseline. */
+function getSkeletonSigns(count: number, seed = 0): number[] {
+  return Array.from({ length: count }, (_, i) =>
+    hashFract((i + 1) * 78.233 + seed) < 0.5 ? -1 : 1
+  );
