+  return Array.from({ length: steps }, (_, i) => {
+    const t = i / (steps - 1);
+    const eased = Math.sin(t * Math.PI) ** 2;
+    const opacity = minOpacity + eased * (maxOpacity - minOpacity);
+    return {
+      offset: `${(t * 100).toFixed(0)}%`,
+      opacity: Number(opacity.toFixed(3)),
