+
+function buildAutoFutureValues(options: {
+  anchorTime: number;
+  anchorValue: number;
+  autoMethod: ProjectionAutoMethod;
+  historyPoints: { t: number; y: number }[];
+  horizonPoints: number;
+  intervalMs: number;
+  pathDensity: ProjectionPathDensity;
+}): ProjectionPoint[] {
+  const {
+    anchorTime,
+    anchorValue,
+    autoMethod,
+    historyPoints,
+    horizonPoints,
+    intervalMs,
+    pathDensity,
+  } = options;
