+export interface SeriesMarkersProps extends SeriesPointMarkerStyle {
+  dataKey: string;
+  /** Marker fill color. Defaults to series stroke or chart palette color. */
+  fill?: string;
+  /** Whether to animate markers with clip reveal. Default: true */
+  animate?: boolean;
+}
+
+interface PointAt {
+  index: number;
+  cx: number;
+  cy: number;
+  revealDelay: number;
+}
+
+interface MarkerStyle {
+  fill: string;
+  stroke: string;
+  strokeWidth: number;
+  ringGap: number;
+  outlineWidth: number;
+  outlineColor?: string;
+  radius: number;
