+      <g>
+        {points.map((point) => (
+          <SeriesPointMarker
+            cx={point.cx}
+            cy={point.cy}
+            dataKey={dataKey}
+            enterBlur={enterBlur}
+            enterDuration={enterDuration}
+            index={point.index}
+            key={`${dataKey}-${point.index}`}
+            revealDelay={point.revealDelay}
+            revealEpoch={revealEpoch ?? 0}
+            {...markerStyle}
