+        dataKey,
+        innerWidth,
+        xDomainMin: xScaleDomain[0]?.getTime?.() ?? 0,
+        xDomainMax: xScaleDomain[1]?.getTime?.() ?? 0,
+      }),
+    [renderData, xAccessor, dataKey, innerWidth, xScaleDomain]
+  );
