+    const timer = window.setTimeout(() => {
+      setChartPhase("ready");
+      setIsLoaded(true);
+    }, animationDuration);
+    return () => window.clearTimeout(timer);
+  }, [animationDuration, chartPhase]);
+
+  return {
+    chartPhase,
+    plotData,
+    revealEpoch,
+    concealEpoch,
+    isLoaded,
+    notifyLoadingPulseComplete,
+    notifyRevealConcealComplete,
+    notifyYDomainTweenComplete,
+  };
+}

