+          animatePosition={xDomain == null}
+          crosshairX={crosshairX}
+          hoveredLabel={hoveredLabel}
+          isHovering={isHovering}
+          key={`${item.date.getTime()}-${item.x}`}
+          label={item.label}
+          tickerHalfWidth={tickerHalfWidth}
+          x={item.x}
+        />
+      ))}
+    </div>,
+    container
+  );
+});
+
